"""Synthetic observed trajectories for the PS-1 probe's P2 analysis. SYNTHETIC: invented graphs, units and steps.

A trajectory is generated by the movement model of ``evaluation/ps1_model.py`` under a chosen rule set and recorded
as the analysis's tables, one row per own ground unit and decision, as an engine observation would show it: the unit's
hex, remaining path, ``speed`` (0 while it waits in front of a full hex or has no order, ``1 / tau`` while it
traverses), keep flag and listed actions. The rule sets are M1c (the frozen post-hoc model), M1b (no wait at entry),
M1 (no restart: a blocked unit enters in the first step with room) and M1c with descending processing (the unit
order reversed inside the model), so each targeted claim can be shown to hold on M1c data and to fail on its rival's.
"""

from __future__ import annotations

import importlib.util
from dataclasses import replace
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

from miaosuan_agent.evaluation import ps1_model as pm

ROOT = Path(__file__).resolve().parents[2]
_spec = importlib.util.spec_from_file_location("ps1_probe_analysis", ROOT / "scripts" / "ps1_probe_analysis.py")
analysis = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(analysis)

FLIP = 10 ** 6


def graph(pairs: Iterable[Tuple[int, int]], cost: float = 1.0) -> Dict[int, Dict[int, Dict[int, float]]]:
    edges: Dict[int, Dict[int, float]] = {}
    for a, b in pairs:
        edges.setdefault(a, {})[b] = cost
        edges.setdefault(b, {})[a] = cost
    return {m: edges for m in range(4)}


def line(n: int) -> Dict[int, Dict[int, Dict[int, float]]]:
    return graph((i, i + 1) for i in range(1, n))


def generate(units: Sequence[pm.Unit], edges: Mapping[int, pm.Edges], steps: int,
             orders: Optional[Mapping[int, Sequence[Tuple[str, int, Tuple[int, ...]]]]] = None, rules: str = "M1c",
             keep: Optional[Mapping[Tuple[int, int], bool]] = None, objectives: Optional[Dict[int, int]] = None,
             surrogate: bool = False, faction: int = 0,
             remove: Optional[Mapping[int, Sequence[int]]] = None) -> Tuple[Any, List[Tuple[str, int, int, int]]]:
    """Run the model for ``steps`` decisions; return ``analysis.Tables`` (both channels identical) and the orders and
    occupations it applied, as (kind, decision index, unit, destination or objective hex). ``remove`` takes units out
    of the game before the observation of a decision index (as when a unit is destroyed or boards)."""
    flip = rules == "descending"
    mapped = [replace(u, uid=FLIP - u.uid) if flip else u for u in units]
    sim = pm.Simulation(units=list(mapped), edges_by_mode=edges, step=0, objectives=dict(objectives or {}),
                        faction=faction, restart_after_wait=rules in ("M1c", "M1b", "descending"),
                        wait_at_entry=rules in ("M1c", "descending"))
    b: Dict[int, Dict[int, Any]] = {}
    cities = {}
    keep = keep or {}
    for k in range(steps + 1):
        for uid in (remove or {}).get(k, ()):
            target = FLIP - uid if flip else uid
            sim.units = [u for u in sim.units if u.uid != target]
        rows = {}
        for u in sim.units:
            uid = FLIP - u.uid if flip else u.uid
            blocked = u.waiting or (u.ready_at is not None and u.ready_at <= k and rules == "M1")
            speed = 0 if (not u.path or blocked or u.ready_at is None) else round(1 / pm.hex_time(u.speed, 1), 6)
            rows[uid] = analysis.Row(u.hex, tuple(u.path), speed, keep.get((k, uid), False), 0, u.speed, 2, 0, 0, 1,
                                     frozenset({10} if u.path else {1}))
        b[k] = rows
        cities[k] = {h: (10, flag) for h, flag in sim.objectives.items()}
        if k == steps:
            break
        if surrogate:
            pm.surrogate(sim)
        for kind, uid, path in (orders or {}).get(k, ()):
            target = FLIP - uid if flip else uid
            if kind == "move":
                sim.order_move(target, path)
            elif kind == "occupy":
                sim.occupy(target)
            elif kind == "stop":
                sim.order_stop(target)
        sim.advance()
    ks = list(range(steps + 1))
    log = []
    for e in sim.events:
        uid = (FLIP - e.uid if flip else e.uid) if e.uid is not None else None
        if e.kind == "order":
            log.append(("move", e.step, uid, e.detail[0]))
        elif e.kind == "occupy":
            log.append(("occupy", e.step, uid, b[e.step][uid].hex))
    tables = analysis.Tables(ks, b, {k: dict(v) for k, v in b.items()}, {k: k for k in ks}, {k: 2 for k in ks}, cities,
                             {k: 0 for k in ks}, {k: 0 for k in ks}, frozenset())
    return tables, log


SPEED = 144.0  # tau = 5 steps per cost-1 hex


def contention_case(rules: str = "M1c", steps: int = 60) -> Any:
    """Hex 3 holds two holders and two units leaving at step 8; unit 9 waits in front of it from early on, units 5 and
    6 enter hex 2 later and wait at once (M1c); when the two places free up, the three restart together and only two
    get in: an arbitration in which ascending index (5, 6) and first come (9 first) disagree."""
    units = [pm.Unit(1, 3, SPEED, 0), pm.Unit(2, 3, SPEED, 0), pm.Unit(3, 3, SPEED, 0), pm.Unit(4, 3, SPEED, 0),
             pm.Unit(9, 2, SPEED, 0), pm.Unit(5, 1, SPEED, 0), pm.Unit(6, 1, SPEED, 0)]
    orders = {0: [("move", 9, (3,))], 2: [("move", 5, (2, 3)), ("move", 6, (2, 3))],
              14: [("move", 1, (4, 5)), ("move", 2, (4, 5))]}
    return generate(units, line(5), steps, orders, rules)[0], orders


def refill_case(rules: str = "M1c", steps: int = 80) -> Any:
    """Unit 7 waits in front of hex 3; room appears, it restarts, and the hex refills before its traversal ends
    (re-wait); room appears again and it gets in."""
    units = [pm.Unit(i, 3, SPEED, 0) for i in (1, 2, 3, 4)] + [pm.Unit(7, 2, SPEED, 0), pm.Unit(8, 4, SPEED, 0)]
    orders = {0: [("move", 7, (3,))], 9: [("move", 1, (4, 5))], 11: [("move", 8, (3, 2, 1))],
              30: [("move", 2, (4, 5))]}
    return generate(units, line(5), steps, orders, rules)[0], orders
